import { useEffect, useRef, useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import { jwtDecode } from "jwt-decode";
import { isAction } from "@reduxjs/toolkit";
import PageTable from "./PageTable";

function Page() {
  const API_URL = process.env.REACT_APP_API_URL;
  const [template, setTemplate] = useState([]);
  const [isSlugGenerated, setIsSlugGenerated] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [allPage, setAllpage] = useState([]);
  const [isEdit, setIsEdit] = useState(false);
  const [editId, setEditId] = useState(null);
  const [preview, setPreview] = useState(null);
  const [data, setData] = useState({
    pageTitle: "",
    slug: "",
    subtitle: "",
    metaDescription: "",
    designTemplate: "",
    keyword: "",
    seoPageType: "",
    imageTitle: "",
    photo: null,
  });

  const token = localStorage.getItem("token");
  const formRef = useRef();

  const getTemplate = async (page = 1, combinedData = []) => {
    try {
      const response = await axios.get(
        `${API_URL}/templates/list?page=${page}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      const newCombinedData = [...combinedData, ...response.data.data];
      if (page < response.data.totalPages) {
        return getTemplate(page + 1, newCombinedData);
      } else {
        setTemplate(newCombinedData);
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      if (
        error.response?.data?.message === "Invalid token" ||
        error.response?.status === 401
      ) {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
    }
  };

  const handleChange = (e) => {
    const { name, value, type, files } = e.target;

    if (type === "file") {
      const file = files[0];

      setData({
        ...data,
        [name]: file,
      });

      if (file) {
        setPreview(URL.createObjectURL(file));
      }
    } else {
      if (name === "slug") {
        setData({
          ...data,
          [name]: value.replace(/\s+/g, "-").toLowerCase(),
        });
        setIsSlugGenerated(true);
      } else {
        setData({
          ...data,
          [name]: value,
        });
      }
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isEdit) {
      try {
        const formData = new FormData();

        formData.append("pageTitle", data?.pageTitle);
        formData.append("slug", data?.slug);
        formData.append("subtitle", data?.subtitle);
        formData.append("metaDescription", data?.metaDescription);
        formData.append("designTemplate", data?.designTemplate);
        formData.append("keyword", data?.keyword);
        formData.append("seoPageType", data?.seoPageType);
        formData.append("imageTitle", data?.imageTitle);

        if (data?.photo) {
          formData.append("photo", data.photo);
        }

        formData.append("isActive", data?.isActive);

        const res = await axios.put(
          `${API_URL}/pages/update/${editId}`,
          formData,
          {
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "multipart/form-data",
            },
          },
        );

        console.log("res", res?.data?.message);

        setData({
          pageTitle: "",
          slug: "",
          subtitle: "",
          metaDescription: "",
          designTemplate: "",
          keyword: "",
          seoPageType: "",
          imageTitle: "",
          photo: null,
        });

        setPreview(null);
        formRef.current.reset();

        getAllPage(currentPage);
      } catch (error) {
        Swal.fire({
          icon: "error",
          title: "Error",
          text: error?.response?.data?.message || "Update failed",
        });
      }
    } else {
      const formData = new FormData();

      formData.append("pageTitle", data?.pageTitle);
      formData.append("slug", data?.slug);
      formData.append("subtitle", data?.subtitle);
      formData.append("metaDescription", data?.metaDescription);
      formData.append("designTemplate", data?.designTemplate);
      formData.append("keyword", data?.keyword);
      formData.append("seoPageType", data?.seoPageType);
      formData.append("imageTitle", data?.imageTitle);
      formData.append("photo", data?.photo);

      try {
        const response = await axios.post(`${API_URL}/pages/create`, formData, {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "multipart/form-data",
          },
        });

        setData({
          pageTitle: "",
          slug: "",
          subtitle: "",
          metaDescription: "",
          designTemplate: "",
          keyword: "",
          seoPageType: "",
          imageTitle: "",
          photo: null,
        });
        setPreview(null);

        formRef.current.reset();
        getAllPage(currentPage);
      } catch (error) {
        Swal.fire({
          icon: "error",
          title: "Error",
          text: error?.response?.data?.message || "Server error",
        });
      }
    }
  };

  const handleSlugClick = () => {
    if (!isSlugGenerated) {
      setData({
        ...data,
        slug: data.pageTitle.replace(/\s+/g, "-").toLowerCase(),
      });
      setIsSlugGenerated(true);
    }
  };

  const getAllPage = async (page = 1) => {
    try {
      const response = await axios.get(
        // `${API_URL}/pages/allPage?page=${page}`,
        `${API_URL}/pages/allPage?all=true`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      setAllpage(response.data);
      // setCurrentPage(response?.data?.page);
      setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error("Error fetching data:", error);
      if (error.response?.data?.message === "Invalid token") {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
      if (error.response?.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
    }
  };

  useEffect(() => {
    getAllPage(currentPage);
    getTemplate();
  }, []);

  const handleToggle = async (item) => {
    try {
      const token = localStorage.getItem("token");
      const decoded = jwtDecode(token);

      const res = await axios.put(
        `${API_URL}/pages/status/${item?._id}`,
        {
          isActive: !item?.isActive,
          updateby: decoded?.id,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );
      getAllPage(currentPage);
    } catch (error) {
      console.error("Status update error", error);
    }
  };

  const handleEdit = (item) => {
    setData({
      pageTitle: item?.pageTitle,
      slug: item?.slug,
      metaDescription: item?.metaDescription,
      designTemplate: item?.designTemplate?._id,
      subtitle: item?.subtitle,
      keyword: item?.keyword,
      seoPageType: item?.seoPageType,
      imageTitle: item?.imageTitle,
      photo: null,
      isActive: item.isActive,
    });

    setPreview(`http://localhost:5001/uploads/${item?.photo}`);
    setEditId(item._id);
    setIsEdit(true);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  return (
    <>
      <div>
        <div style={{ width: "90%", marginLeft: "5%", marginTop: "3vh" }}>
          <div className="card card-info card-outline mb-4">
            <div className="card-header">
              <div className="card-title">Create page</div>
            </div>

            <form
              className="needs-validation"
              ref={formRef}
              onSubmit={handleSubmit}
            >
              <div className="card-body">
                <div className="row g-3">
                  <div className="col-md-6">
                    <label htmlFor="validationCustom01" className="form-label">
                      Page Title
                    </label>
                    <input
                      type="text"
                      name="pageTitle"
                      value={data?.pageTitle}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom01"
                      required
                    />
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom02" className="form-label">
                      Display URL
                    </label>
                    <input
                      type="text"
                      name="slug"
                      value={data?.slug}
                      onChange={handleChange}
                      onFocus={handleSlugClick}
                      className="form-control"
                      id="validationCustom02"
                      required
                    />
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom01" className="form-label">
                      Sub-Title
                    </label>
                    <input
                      type="text"
                      name="subtitle"
                      value={data?.subtitle}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom01"
                      required
                    />
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Meta Description
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="metaDescription"
                        value={data?.metaDescription}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        // required
                      />
                      <div className="invalid-feedback">
                        Please choose a Meta Description..
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Key Word
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="keyword"
                        value={data?.keyword}
                        onChange={handleChange}
                        className="form-control"
                        // id="validationCustomUsername"
                        // aria-describedby="inputGroupPrepend"
                        // required
                      />
                      {/* <div className="invalid-feedback">
                        Please choose a Meta Description..
                      </div> */}
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Seo Page Type
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="seoPageType"
                        value={data?.seoPageType}
                        onChange={handleChange}
                        className="form-control"
                        // id="validationCustomUsername"
                        // aria-describedby="inputGroupPrepend"
                        // required
                      />
                      {/* <div className="invalid-feedback">
                        Please choose a Meta Description..
                      </div> */}
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Image Title
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="imageTitle"
                        value={data?.imageTitle}
                        onChange={handleChange}
                        className="form-control"
                        // id="validationCustomUsername"
                        // aria-describedby="inputGroupPrepend"
                        // required
                      />
                      {/* <div className="invalid-feedback">
                        Please choose a Meta Description..
                      </div> */}
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom03" className="form-label">
                      Design Template
                    </label>
                    <select
                      name="designTemplate"
                      className="form-control"
                      value={data?.designTemplate}
                      onChange={handleChange}
                      id="validationCustom03"
                    >
                      <option>select</option>
                      {template?.map((item, index) => {
                        return (
                          <option key={index} value={item?._id}>
                            {item?.templateName}
                          </option>
                        );
                      })}
                    </select>

                    <div className="invalid-feedback">
                      Please provide a Design Template.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Photo
                    </label>
                    <input
                      type="file"
                      name="photo"
                      //   value={data?.photo}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                    />
                    {preview && (
                      <div style={{ marginTop: "10px" }}>
                        <img
                          // src={`http://localhost:5001/uploads/${preview}`}
                          src={preview}
                          alt="Preview"
                          style={{
                            width: "100px",
                            height: "100px",
                            objectFit: "cover",
                          }}
                        />
                      </div>
                    )}
                    <div className="invalid-feedback">
                      Please provide a Photo.
                    </div>
                  </div>
                  {isEdit ? (
                    <div className="col-md-6">
                      <label className="form-label">Is Active</label>
                      <select
                        name="isActive"
                        value={data.isActive}
                        onChange={handleChange}
                        className="form-control"
                      >
                        <option value={true}>Active</option>
                        <option value={false}>Inactive</option>
                      </select>
                    </div>
                  ) : (
                    ""
                  )}
                </div>
              </div>

              <div className="card-footer">
                <button className="btn btn-info" type="submit">
                  {/* {isEdit ? "Update User" : "Submit form"} */}
                  {isEdit ? "Update" : "Save"}
                  {/* Save */}
                </button>
              </div>
            </form>
          </div>
        </div>
        <div className="card mb-4" style={{ width: "90%", marginLeft: "5%" }}>
          <PageTable
            data={allPage?.data || []}
            handleToggle={handleToggle}
            handleEdit={handleEdit}
            currentPage={currentPage}
            setCurrentPage={setCurrentPage}
          />
          {/* <div className="card-header">
            <h3 className="card-title">All Page</h3>
          </div>
          <div
            className="card-body"
            style={{
              width: "100%",
              overflow: "auto",
              border: "1px solid #ddd",
            }}
          >
            <table className="table table-bordered">
              <thead>
                <tr>
                  <th style={{ width: "10px" }}>#</th>
                  <th>Page Title</th>
                  <th>Design Template</th>
                  <th>Status</th>
                  <th style={{ width: "40px" }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {allPage?.data?.map((item, index) => (
                  <tr key={index} className="align-middle">
                    <td>{index + 1}</td>
                    <td>{item?.pageTitle}</td>
                    <td>
                      {template.find((t) => t._id === item?.designTemplate?._id)
                        ?.templateName || ""}
                    </td>
                    <td>
                      <div className="form-check form-switch">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          role="switch"
                          checked={item?.isActive}
                          onChange={() => handleToggle(item)}
                        />
                        <label className="form-check-label">
                          {item?.isActive ? "Active" : "Inactive"}
                        </label>
                      </div>
                    </td>

                    <td>
                      <span
                        className="badge text-bg-danger"
                        style={{ cursor: "pointer" }}
                        onClick={() => handleEdit(item)}
                      >
                        Edit
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="card-footer clearfix">
            <ul className="pagination pagination-sm m-0 float-end">
              <li
                className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
              >
                <button
                  className="page-link"
                  onClick={() => getAllPage(currentPage - 1)}
                  disabled={currentPage === 1}
                >
                  &laquo;
                </button>
              </li>
              {Array.from({ length: totalPages }, (_, index) => (
                <li
                  key={index + 1}
                  className={`page-item ${currentPage === index + 1 ? "active" : ""}`}
                >
                  <button
                    className="page-link"
                    onClick={() => getAllPage(index + 1)}
                  >
                    {index + 1}
                  </button>
                </li>
              ))}
              <li
                className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
              >
                <button
                  className="page-link"
                  onClick={() => getAllPage(currentPage + 1)}
                  disabled={currentPage === totalPages}
                >
                  &raquo;
                </button>
              </li>
            </ul>
          </div> */}
        </div>
      </div>
    </>
  );
}

export default Page;
