import axios from "axios";
import { useRef, useState } from "react";
import Swal from "sweetalert2";

function OrganizationDetails() {
  const API_URL = process.env.REACT_APP_API_URL;
  const [preview, setPreview] = useState({
    logo1: null,
    logo2: null,
  });
  const [data, setData] = useState({
    organizationName: "",
    tagLine: "",
    logo1: null,
    logo1Title: "",
    logo2: null,
    logo2Title: "",
    addressLine1: "",
    addressLine2: "",
    city: "",
    state: "",
    pinCode: "",
    contactNumber: "",
    faxNumber: "",
    email1: "",
    email2: "",
    websiteLink: "",
    facebookLink: "",
    twitterLink: "",
    linkedinLink: "",
    youtubeLink: "",
    instagramLink: "",
    googleMapLink: "",
  });

  const token = localStorage.getItem("token");
  const formRef = useRef();

  // const handleChange = (e) => {
  //   const { name, value, type, files } = e.target;

  //   if (type === "file") {
  //     const file = files[0];
  //     setData((prev) => ({
  //       ...prev,
  //       [name]: file,
  //     }));
  //   } else {
  //     setData((prev) => ({
  //       ...prev,
  //       [name]: value,
  //     }));
  //   }
  // };

  const handleChange = (e) => {
    const { name, type, files } = e.target;

    if (type === "file" && files.length > 0) {
      const file = files[0];

      setData((prev) => ({
        ...prev,
        [name]: file,
      }));

      setPreview((prev) => ({
        ...prev,
        [name]: URL.createObjectURL(file),
      }));
    } else {
      setData((prev) => ({
        ...prev,
        [e.target.name]: e.target.value,
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();

    formData.append("organizationName", data?.organizationName);
    formData.append("tagLine", data?.tagLine);
    formData.append("logo1", data?.logo1);
    formData.append("logo1Title", data?.logo1Title);
    formData.append("logo2", data?.logo2);
    formData.append("logo2Title", data?.logo2Title);
    formData.append("addressLine1", data?.addressLine1);
    formData.append("addressLine2", data?.addressLine2);
    formData.append("city", data?.city);
    formData.append("state", data?.state);
    formData.append("pinCode", data?.pinCode);
    formData.append("contactNumber", data?.contactNumber);
    formData.append("faxNumber", data?.faxNumber);
    formData.append("email1", data?.email1);
    formData.append("email2", data?.email2);
    formData.append("websiteLink", data?.websiteLink);
    formData.append("facebookLink", data?.facebookLink);
    formData.append("twitterLink", data?.twitterLink);
    formData.append("linkedinLink", data?.linkedinLink);
    formData.append("youtubeLink", data?.youtubeLink);
    formData.append("instagramLink", data?.instagramLink);
    formData.append("googleMapLink", data?.googleMapLink);

    try {
      const response = await axios.post(
        `${API_URL}/organization/createOrganization`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "multipart/form-data",
          },
        },
      );

      console.log("response", response);

      setData({
        organizationName: "",
        tagLine: "",
        logo1: null,
        logo1Title: "",
        logo2: null,
        logo2Title: "",
        addressLine1: "",
        addressLine2: "",
        city: "",
        state: "",
        pinCode: "",
        contactNumber: "",
        faxNumber: "",
        email1: "",
        email2: "",
        websiteLink: "",
        facebookLink: "",
        twitterLink: "",
        linkedinLink: "",
        youtubeLink: "",
        instagramLink: "",
        googleMapLink: "",
      });
      // setPreview(null);

      formRef.current.reset();
      // getAllPage(currentPage);

      Swal.fire({
        icon: "success",
        title: "Organization Details",
        text: response.data.message || "Organization Details Successfully.",
        confirmButtonColor: "#3085d6",
      });
    } catch (error) {
      Swal.fire({
        icon: "error",
        title: "Error",
        text: error?.response?.data?.message || "Server error",
      });
    }
  };
  return (
    <>
      <div>
        <div style={{ width: "90%", marginLeft: "5%", marginTop: "3vh" }}>
          <div className="card card-info card-outline mb-4">
            <div className="card-header">
              <div className="card-title">Organization Details</div>
            </div>

            <form
              className="needs-validation"
              ref={formRef}
              onSubmit={handleSubmit}
            >
              <div className="card-body">
                <div className="row g-3">
                  <div className="col-md-6">
                    <label htmlFor="validationCustom01" className="form-label">
                      Organization Name
                    </label>
                    <input
                      type="text"
                      name="organizationName"
                      value={data?.organizationName}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom01"
                      required
                    />
                    <div className="valid-feedback">
                      Please provide a Organization Name
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom02" className="form-label">
                      Tag Line
                    </label>
                    <input
                      type="text"
                      name="tagLine"
                      value={data?.tagLine}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom02"
                      required
                    />
                    <div className="valid-feedback">
                      Please provide a Tag Line
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Logo 1
                    </label>
                    <input
                      type="file"
                      name="logo1"
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                      required
                    />
                    {preview && (
                      <img
                        src={preview?.logo1}
                        alt="Preview"
                        style={{
                          marginTop: "10px",
                          width: "100px",
                          height: "100px",
                          objectFit: "cover",
                        }}
                      />
                    )}
                    <div className="invalid-feedback">
                      Please provide a Logo 1.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Logo 1 Title
                    </label>
                    <input
                      type="text"
                      name="logo1Title"
                      value={data?.logo1Title}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                    />
                    <div className="invalid-feedback">
                      Please provide a Logo 1 Title.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Logo 2
                    </label>
                    <input
                      type="file"
                      name="logo2"
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                    />
                    {preview && (
                      <img
                        src={preview?.logo2}
                        alt="Preview"
                        style={{
                          marginTop: "10px",
                          width: "100px",
                          height: "100px",
                          objectFit: "cover",
                        }}
                      />
                    )}
                    <div className="invalid-feedback">
                      Please provide a Logo 2.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Logo 2 Title
                    </label>
                    <input
                      type="text"
                      name="logo2Title"
                      value={data?.logo2Title}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                    />
                    <div className="invalid-feedback">
                      Please provide a Logo 2 title.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Address Line 1
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="addressLine1"
                        value={data?.addressLine1}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Address Line 1
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Address Line 2
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="addressLine2"
                        value={data?.addressLine2}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Address Line 2
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      City
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="city"
                        value={data?.city}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a City
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      state
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="state"
                        value={data?.state}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a state
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      PIN Code Number
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="number"
                        name="pinCode"
                        value={data?.pinCode}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a PIN Code number
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Contact Number
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="number"
                        name="contactNumber"
                        value={data?.contactNumber}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Contact Number
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Fax Number
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="tel"
                        name="faxNumber"
                        value={data?.faxNumber}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Fax Number
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Email ID 1
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="email"
                        name="email1"
                        value={data?.email1}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Email 1
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Email ID 2
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="email"
                        name="email2"
                        value={data?.email2}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Email 1
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Website link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="websiteLink"
                        value={data?.websiteLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Website Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Facebook Link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="facebookLink"
                        value={data?.facebookLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Facebook Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Twitter (X) Link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="twitterLink"
                        value={data?.twitterLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Twitter (X) Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      LinkedIn link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="linkedinLink"
                        value={data?.linkedinLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a LinkedIn Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      YouTube link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="youtubeLink"
                        value={data?.youtubeLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a YouTube Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Instagram Link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="instagramLink"
                        value={data?.instagramLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                      />
                      <div className="invalid-feedback">
                        Please choose a Instagram Link
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Google Map Location Link
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="googleMapLink"
                        value={data?.googleMapLink}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Google Map Location Link
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="card-footer">
                <button className="btn btn-info" type="submit">
                  Save
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </>
  );
}

export default OrganizationDetails;
