import axios from "axios";
import { jwtDecode } from "jwt-decode";
import { useEffect, useState } from "react";
import Swal from "sweetalert2";
import MenuTable from "./MenuTable";

function Menu() {
  const API_URL = process.env.REACT_APP_API_URL;
  const token = localStorage.getItem("token");

  const [isPage, setIsPage] = useState("");
  const [menu, setMenu] = useState([]);
  const [pages, setPages] = useState([]);
  const [error, setError] = useState({});
  const [isEdit, setIsEdit] = useState(false);
  const [editId, setEditId] = useState(null);
  const [data, setData] = useState({
    menuType: "",
    parentMenuId: "",
    menuName: "",
    pageId: "",
    customUrl: "",
    order: "",
    isActive: "",
  });

  const isValidUrl = (url) => {
    const pattern = /^(https?:\/\/)(([a-zA-Z0-9\-]+\.)+[a-zA-Z]{2,})(\/.*)?$/;
    return pattern.test(url);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;

    setData((prev) => {
      let updated = {
        ...prev,
        [name]: value,
      };

      //menuType change logic
      if (name === "menuType") {
        if (value === "parent") {
          updated.parentMenuId = "";
        }
      }

      // isPage change logic
      if (name === "isPage") {
        setIsPage(value);

        if (value === "yes") {
          updated.customUrl = "";
        }

        if (value === "no") {
          updated.pageId = "";
        }
      }

      return updated;
    });
    if (name === "customUrl") {
      if (value && !isValidUrl(value)) {
        setError((prev) => ({
          ...prev,
          customUrl: "Invalid URL (https://example.com)",
        }));
      } else {
        setError((prev) => ({
          ...prev,
          customUrl: "",
        }));
      }
    }
  };

  const getmenu = async () => {
    try {
      const response = await axios.get(`${API_URL}/menu/getmenu`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setMenu(response.data);
    } catch (error) {
      console.error("Error fetching data:", error);
      if (error.response?.data?.message === "Invalid token") {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
      if (error.response?.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
    }
  };

  const getpages = async () => {
    try {
      const response = await axios.get(`${API_URL}/pages/allPage?all=true`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setPages(response.data);
      // setCurrentPage(response.data.page);
      // setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error("Error fetching data:", error);
      if (error.response?.data?.message === "Invalid token") {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
      if (error.response?.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
    }
  };

  useEffect(() => {
    getmenu();
    getpages();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (isEdit) {
      const res = await axios.put(`${API_URL}/menu/update/${editId}`, data, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      console.log("res", res);

      setIsEdit(false);

      setData({
        menuType: "",
        parentMenuId: "",
        menuName: "",
        pageId: "",
        customUrl: "",
        order: "",
        isActive: "",
      });
      setIsPage("");
      getmenu();
    } else {
      try {
        const response = await axios.post(`${API_URL}/menu/createmenu`, data, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        console.log("response", response);

        setData({
          menuType: "",
          parentMenuId: "",
          menuName: "",
          pageId: "",
          customUrl: "",
          order: "",
          isActive: "",
        });
        setIsPage("");
        getmenu();
      } catch (error) {
        console.log("FULL ERROR:", error);
        console.log("SERVER ERROR:", error?.response?.data);

        Swal.fire({
          icon: "error",
          title: "Error",
          text: error?.response?.data?.message || "Server error",
        });
      }
    }
  };

  const handleToggle = async (item) => {
    try {
      const decoded = jwtDecode(token);

      const res = await axios.put(
        `${API_URL}/menu/status/${item._id}`,
        {
          isActive: !item.isActive,
          updateby: decoded.id,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      console.log(res.data);
      getmenu();
    } catch (error) {
      console.error("Status update error", error);
    }
  };

  const handleEdit = (item) => {
    const isPageValue = item?.pageId ? "yes" : "no";

    setData({
      menuType: item?.menuType,
      parentMenuId: item?.parentMenuId?._id || item?.parentMenuId || "",
      menuName: item?.menuName,
      pageId: item?.pageId?._id || item?.pageId || "",
      customUrl: item?.customUrl,
      order: item?.order,
      isActive: item?.isActive,
    });
    setIsPage(isPageValue);
    setIsEdit(true);
    setEditId(item?._id);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  return (
    <>
      <div>
        <div style={{ width: "90%", marginLeft: "5%", marginTop: "3vh" }}>
          <div className="card card-info card-outline mb-4">
            <div className="card-header">
              <div className="card-title">Create Menu</div>
            </div>

            <form
              className="needs-validation"
              //   ref={formRef}
              onSubmit={handleSubmit}
            >
              <div className="card-body">
                <div className="row g-3">
                  <div className="col-md-6">
                    <label htmlFor="validationCustom01" className="form-label">
                      Menu Type
                    </label>
                    <select
                      name="menuType"
                      className="form-control"
                      value={data?.menuType}
                      onChange={handleChange}
                      //   id="validationCustom03"
                    >
                      <option>select</option>
                      <option value="parent">Parent Menu</option>
                      <option value="child">Child Menu</option>
                    </select>
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  {data?.menuType === "child" && (
                    <div className="col-md-6">
                      <label
                        htmlFor="validationCustom02"
                        className="form-label"
                      >
                        Parent Menu
                      </label>
                      <select
                        name="parentMenuId"
                        className="form-control"
                        value={String(data.parentMenuId || "")}
                        onChange={handleChange}
                      >
                        {console.log("Menu All Data ", menu)}
                        <option>select</option>
                        {menu?.data
                          ?.filter(
                            (item) =>
                              item.isActive === true &&
                              item.menuType == "parent",
                          )
                          .map((item, index) => {
                            return (
                              <option key={index} value={String(item._id)}>
                                {item?.menuName}
                              </option>
                            );
                          })}
                        ;
                      </select>
                    </div>
                  )}

                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Menu Name
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="text"
                        name="menuName"
                        value={data?.menuName}
                        onChange={handleChange}
                        className="form-control"
                        id="validationCustomUsername"
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Menu Name..
                      </div>
                    </div>
                  </div>

                  <div className="col-md-6">
                    <label htmlFor="validationCustom03" className="form-label">
                      Is Page
                    </label>
                    <select
                      name="isPage"
                      value={isPage}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom03"
                    >
                      <option value="">select</option>
                      <option value="yes">Yes</option>
                      <option value="no">No</option>
                    </select>
                    <div className="invalid-feedback">
                      Please provide a Is page.
                    </div>
                  </div>

                  {isPage === "yes" && (
                    <div className="col-md-6">
                      <label
                        htmlFor="validationCustom03"
                        className="form-label"
                      >
                        Page Name
                      </label>
                      <select
                        name="pageId"
                        className="form-control"
                        value={data?.pageId}
                        onChange={handleChange}
                        id="validationCustom03"
                      >
                        <option>select</option>
                        {pages?.data?.map((item, index) => {
                          return (
                            <option key={index} value={item?._id}>
                              {item?.pageTitle}
                            </option>
                          );
                        })}
                      </select>
                      <div className="invalid-feedback">
                        Please provide a Page Name.
                      </div>
                    </div>
                  )}
                  {isPage === "no" && (
                    <div className="col-md-6">
                      <label
                        htmlFor="validationCustom03"
                        className="form-label"
                      >
                        Coustom Url (Link)
                      </label>
                      <input
                        type="url"
                        name="customUrl"
                        value={data?.customUrl}
                        onChange={handleChange}
                        className={`form-control ${error.customUrl ? "is-invalid" : ""}`}
                        id="validationCustom03"
                      />
                      {error.customUrl && (
                        <div className="invalid-feedback">
                          {error.customUrl}
                        </div>
                      )}
                      <div className="invalid-feedback">
                        Please provide a Coustom Url (Link).
                      </div>
                    </div>
                  )}

                  <div className="col-md-6">
                    <label className="form-label">Order</label>
                    {/* <select
                      name="order"
                      value={data?.order}
                      onChange={handleChange}
                      className="form-control"
                    >
                      <option value={""}>select</option>
                      <option value={"1"}>1</option>
                      <option value={"2"}>2</option>
                    </select> */}

                    <input
                      type="number"
                      name="order"
                      value={data?.order}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustomUsername"
                      aria-describedby="inputGroupPrepend"
                      required
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label">Is Active</label>
                    <select
                      name="isActive"
                      value={data?.isActive}
                      onChange={handleChange}
                      className="form-control"
                    >
                      <option value={true}>Active</option>
                      <option value={false}>Inactive</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="card-footer">
                <button className="btn btn-info" type="submit">
                  {/* {isEdit ? "Update User" : "Submit form"} */}
                  {isEdit ? "Update" : "Save"}
                  {/* Save */}
                </button>
              </div>
            </form>
          </div>
        </div>
        <div className="card mb-4" style={{ width: "90%", marginLeft: "5%" }}>
          <MenuTable
            data={menu?.data || []}
            handleToggle={handleToggle}
            handleEdit={handleEdit}
          />
        </div>
        {/* <div className="card mb-4" style={{ width: "90%", marginLeft: "5%" }}>
          <div className="card-header">
            <h3 className="card-title">All Menu</h3>
          </div>
          <div
            className="card-body"
            style={{
              width: "100%",
              overflow: "auto",
              border: "1px solid #ddd",
            }}
          >
            <table className="table table-bordered">
              <thead>
                <tr>
                  <th style={{ width: "10px" }}>#</th>
                  <th>Menu Type</th>
                  <th>Menu Name</th>
                  <th>Order</th>
                  <th>Status</th>
                  <th style={{ width: "40px" }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {menu?.data?.map((item, index) => (
                  <tr key={index} className="align-middle">
                    <td>{index + 1}</td>
                    <td>{item?.menuType}</td>
                    <td>{item?.menuName}</td>
                    <td>{item?.order}</td>
                    <td>
                      <div className="form-check form-switch">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          role="switch"
                          checked={Boolean(item?.isActive)}
                          onChange={() => handleToggle(item)}
                        />
                        <label className="form-check-label">
                          {item?.isActive ? "Active" : "Inactive"}
                        </label>
                      </div>
                    </td>

                    <td>
                      <span
                        className="badge text-bg-danger"
                        style={{ cursor: "pointer" }}
                        onClick={() => handleEdit(item)}
                      >
                        Edit
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="card-footer clearfix">
           
          </div>
        </div> */}
      </div>
    </>
  );
}

export default Menu;
