import axios from "axios";
import { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { useRef } from "react";
import { jwtDecode } from "jwt-decode";
import UserTable from "./UserTable";

function User() {
  const itemsPerPage = 10;
  const API_URL = process.env.REACT_APP_API_URL;
  const [isEdit, setIsEdit] = useState(false);
  const [editId, setEditId] = useState(null);
  const [users, setUsers] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [preview, setPreview] = useState(null);
  const [createUser, setCreateUser] = useState({
    name: "",
    email: "",
    mobileNo: "",
    password: "",
    designation: "",
    photo: "",
    imageTitle: "",
  });

  const token = localStorage.getItem("token");
  const formRef = useRef();

  const handleEdit = (user) => {
    setCreateUser({
      name: user.name,
      email: user.email,
      mobileNo: user.mobileNo,
      password: user.password,
      designation: user.designation,
      imageTitle: user.imageTitle,
      photo: "",
      isActive: user.isActive,
    });
    setPreview(`http://localhost:5001/uploads/${user.photo}`);
    setEditId(user._id);
    setIsEdit(true);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  const handleChange = (e) => {
    const { name, value, type, files } = e.target;

    if (type === "file") {
      const file = files[0];
      setCreateUser({
        ...createUser,
        [name]: file,
      });
      setPreview(URL.createObjectURL(file));
    } else {
      setCreateUser({
        ...createUser,
        [name]: value,
      });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (isEdit) {
      const formData = new FormData();

      if (createUser.name) {
        formData.append("name", createUser.name);
      }

      if (createUser.mobileNo) {
        formData.append("mobileNo", createUser.mobileNo);
      }

      if (createUser.designation) {
        formData.append("designation", createUser.designation);
      }

      if (createUser.password) {
        formData.append("password", createUser.password);
      }

      if (createUser.photo) {
        formData.append("photo", createUser.photo);
      }
      if (createUser.imageTitle) {
        formData.append("imageTitle", createUser.imageTitle);
      }

      await axios.put(`${API_URL}/users/update/${editId}`, formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "multipart/form-data",
        },
      });

      setIsEdit(false);

      setCreateUser({
        name: "",
        email: "",
        mobileNo: "",
        password: "",
        designation: "",
        photo: null,
        imageTitle: "",
        isActive: true,
      });
      formRef.current.reset();
      setPreview(null);
    } else {
      const formData = new FormData();

      formData.append("name", createUser.name);
      formData.append("email", createUser.email);
      formData.append("mobileNo", createUser.mobileNo);
      formData.append("password", createUser.password);
      formData.append("designation", createUser.designation);
      formData.append("imageTitle", createUser.imageTitle);
      formData.append("photo", createUser.photo);

      try {
        const response = await axios.post(`${API_URL}/users`, formData, {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "multipart/form-data",
          },
        });

        console.log("response", response);

        setCreateUser({
          name: "",
          email: "",
          mobileNo: "",
          password: "",
          designation: "",
          photo: null,
          imageTitle: "",
        });
        formRef.current.reset();
        setPreview(null);
      } catch (error) {
        console.log("FULL ERROR:", error);
        console.log("SERVER ERROR:", error?.response?.data);

        Swal.fire({
          icon: "error",
          title: "Error",
          text: error?.response?.data?.message || "Server error",
        });
      }
    }
    getUsers(currentPage);
  };

  const getUsers = async (page = 1) => {
    try {
      // const response = await axios.get(`${API_URL}/users?page=${page}`, {
      const response = await axios.get(`${API_URL}/users?all=true`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      setUsers(response.data);
      setCurrentPage(response.data.page);
      setTotalPages(response.data.totalPages);
    } catch (error) {
      console.error("Error fetching data:", error);
      if (error.response?.data?.message === "Invalid token") {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
      if (error.response?.status === 401) {
        localStorage.removeItem("token");
        window.location.href = "/login";
      }
    }
  };

  useEffect(() => {
    getUsers(currentPage);
  }, []);

  const handleToggle = async (user) => {
    try {
      const token = localStorage.getItem("token");
      const decoded = jwtDecode(token);

      const res = await axios.put(
        `${API_URL}/users/status/${user._id}`,
        {
          isActive: !user.isActive,
          updateby: decoded.id,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
      );

      console.log(res.data);
      getUsers(currentPage);
    } catch (error) {
      console.error("Status update error", error);
    }
  };
  return (
    <>
      <div>
        <div style={{ width: "90%", marginLeft: "5%", marginTop: "3vh" }}>
          <div className="card card-info card-outline mb-4">
            <div className="card-header">
              <div className="card-title">Create User</div>
            </div>

            <form
              className="needs-validation"
              ref={formRef}
              onSubmit={handleSubmit}
            >
              <div className="card-body">
                <div className="row g-3">
                  <div className="col-md-6">
                    <label htmlFor="validationCustom01" className="form-label">
                      Name
                    </label>
                    <input
                      type="text"
                      name="name"
                      value={createUser.name}
                      className="form-control"
                      id="validationCustom01"
                      onChange={handleChange}
                      required
                    />
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom02" className="form-label">
                      Email Id
                    </label>
                    <input
                      type="email"
                      name="email"
                      value={createUser.email}
                      onChange={handleChange}
                      disabled={isEdit}
                      className="form-control"
                      id="validationCustom02"
                      required
                    />
                    <div className="valid-feedback">Looks good!</div>
                  </div>
                  <div className="col-md-6">
                    <label
                      htmlFor="validationCustomUsername"
                      className="form-label"
                    >
                      Mobile No.
                    </label>
                    <div className="input-group has-validation">
                      <input
                        type="number"
                        name="mobileNo"
                        value={createUser.mobileNo}
                        className="form-control"
                        id="validationCustomUsername"
                        onChange={handleChange}
                        aria-describedby="inputGroupPrepend"
                        required
                      />
                      <div className="invalid-feedback">
                        Please choose a Mobile No..
                      </div>
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom03" className="form-label">
                      Password
                    </label>
                    <input
                      type="password"
                      name="password"
                      value={createUser.password}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom03"
                      required={!isEdit}
                    />
                    <div className="invalid-feedback">
                      Please provide a Password.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom03" className="form-label">
                      Designation
                    </label>
                    <input
                      type="text"
                      name="designation"
                      value={createUser.designation}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom03"
                      required
                    />
                    <div className="invalid-feedback">
                      Please provide a Designation.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom03" className="form-label">
                      Image Title
                    </label>
                    <input
                      type="text"
                      name="imageTitle"
                      value={createUser?.imageTitle}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom03"
                      // required
                    />
                    <div className="invalid-feedback">
                      Please provide a Designation.
                    </div>
                  </div>
                  <div className="col-md-6">
                    <label htmlFor="validationCustom05" className="form-label">
                      Photo
                    </label>
                    <input
                      type="file"
                      name="photo"
                      // value={createUser.photo}
                      onChange={handleChange}
                      className="form-control"
                      id="validationCustom05"
                      required={!isEdit}
                    />
                    {preview && (
                      <img
                        src={preview}
                        alt="Preview"
                        style={{
                          marginTop: "10px",
                          width: "100px",
                          height: "100px",
                          objectFit: "cover",
                        }}
                      />
                    )}
                    <div className="invalid-feedback">
                      Please provide a Photo.
                    </div>
                  </div>
                  {isEdit ? (
                    <div className="col-md-6">
                      <label className="form-label">Is Active</label>
                      <select
                        name="isActive"
                        value={createUser.isActive}
                        onChange={handleChange}
                        className="form-control"
                      >
                        <option value={true}>Active</option>
                        <option value={false}>Inactive</option>
                      </select>
                    </div>
                  ) : (
                    ""
                  )}
                </div>
              </div>

              <div className="card-footer">
                <button className="btn btn-info" type="submit">
                  {/* {isEdit ? "Update User" : "Submit form"} */}
                  {isEdit ? "Update" : "Save"}
                </button>
              </div>
            </form>
          </div>
        </div>
        <div className="card mb-4" style={{ width: "90%", marginLeft: "5%" }}>
          <UserTable
            data={users?.data || []}
            handleToggle={handleToggle}
            handleEdit={handleEdit}
          />
          {/* <div className="card-header">
            <h3 className="card-title">All User</h3>
          </div>
          <div
            className="card-body"
            style={{
              width: "100%",
              overflow: "auto",
              border: "1px solid #ddd",
            }}
          >
            <table className="table table-bordered">
              <thead>
                <tr>
                  <th style={{ width: "10px" }}>#</th>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Mobile No.</th>
                  <th>Designation.</th>
                  <th>Photo</th>
                  <th>Status</th>
                  <th style={{ width: "40px" }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {users?.data?.map((user, index) => (
                  <tr key={index} className="align-middle">
                    <td>{(currentPage - 1) * itemsPerPage + index + 1}</td>
                    <td>{user?.name}</td>
                    <td>{user?.email}</td>
                    <td>{user?.mobileNo}</td>
                    <td>{user?.designation}</td>
                    <td>
                      <img
                        style={{ height: "10vh", width: "10vw" }}
                        src={`http://localhost:5001/uploads/${user?.photo}`}
                        alt={user?.photo}
                      />
                    </td>
                    <td>
                      <div className="form-check form-switch">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          role="switch"
                          checked={user?.isActive}
                          onChange={() => handleToggle(user)}
                        />
                        <label className="form-check-label">
                          {user?.isActive ? "Active" : "Inactive"}
                        </label>
                      </div>
                    </td>

                    <td>
                      <span
                        className="badge text-bg-danger"
                        style={{ cursor: "pointer" }}
                        onClick={() => handleEdit(user)}
                      >
                        Edit
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="card-footer clearfix">
            <ul className="pagination pagination-sm m-0 float-end">
              <li
                className={`page-item ${currentPage === 1 ? "disabled" : ""}`}
              >
                <button
                  className="page-link"
                  onClick={() => getUsers(currentPage - 1)}
                  disabled={currentPage === 1}
                >
                  &laquo;
                </button>
              </li>
              {Array.from({ length: totalPages }, (_, index) => (
                <li
                  key={index + 1}
                  className={`page-item ${currentPage === index + 1 ? "active" : ""}`}
                >
                  <button
                    className="page-link"
                    onClick={() => getUsers(index + 1)}
                  >
                    {index + 1}
                  </button>
                </li>
              ))}
              <li
                className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}
              >
                <button
                  className="page-link"
                  onClick={() => getUsers(currentPage + 1)}
                  disabled={currentPage === totalPages}
                >
                  &raquo;
                </button>
              </li>
            </ul>
          </div> */}
        </div>
      </div>
    </>
  );
}

export default User;
